cd /workspace/tmp && python3 - <<'EOF'
import sys,json,hashlib; sys.path.insert(0,'/workspace/tmp')
from probe import *
lib=build()
def case(prim,mode,root,K,D,N,evs,trace=0,start=0):
    return {'primitive':prim,'mode':mode,'root':root,'segments':K,'words':D,'capacity':N,
            'start':start,'events':evs,'trace':trace}
def D(r,p,v=None): return {'op':'data','rank':r,'p':p,'values':v} if v else {'op':'data','rank':r,'p':p}
def A(r,u): return {'op':'ack','rank':r,'upto':u}
out={}
for prim in ('allreduce','reduce','broadcast','barrier','allgather','reducescatter'):
    for mode in (2,3):
        K=4 if prim!='barrier' else 1
        D_=1 if prim!='barrier' else 0
        root=1 if prim in ('reduce','broadcast') else 0
        evs=[]
        for p in range(K):
            for r in range(4):
                if prim=='broadcast' and r!=root: continue
                evs.append(D(r,p,[r*7+p]))
        evs+=[A(r,1) for r in range(4)]
        evs+=[{'op':'retry','rank':2},{'op':'flush'},{'op':'snap','tag':'t1'}]
        res=run(case(prim,mode,root,K,D_,8,evs,trace=6,start=100),lib)
        st=res['state']
        key=(prim,mode)
        out[key]=(st[0],st[1],st[6:10],st[10:14],st[14:18],res['packets'])
        print('%-14s mode%d b=%d occ=%d S=%s A=%s U=%s pkts=%d'%(prim,mode,st[0],st[1],st[6:10],st[10:14],st[14:18],res['packets']))
        assert st[30]==0 and st[31]==0
        assert st[18]==st[22]+st[23]+st[24]+st[25]
# determinism check
req=json.dumps({'cases':[case('allgather',3,0,4,1,8,[D(r,p,[r,p]) for p in range(4) for r in range(4)])]})
import subprocess
h=[]
for i in range(2):
    p=subprocess.run(['python3','-I','-B','/workspace/project/solver.py'],input=req.encode(),capture_output=True)
    h.append(hashlib.sha256(p.stdout).hexdigest())
print('deterministic:', h[0]==h[1])
EOF
